from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict | None, key: str) -> Any:
    if not record:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if not tables:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG", "") == "Y":
            continue
        row_key = row.get(key_col, "")
        if row_key is None:
            row_key = ""
        if row_key == key_val:
            value = row.get(out_col, "")
            return "" if value is None else value
    return ""


def _error(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        disc_pct = _number(_value(record, "DISC_PCT"))

        # ORD-001
        if event in ("INSERT", "UPDATE"):
            if not (disc_pct >= 0 and disc_pct <= 100):
                errors.append(_error("E5001", "Discount out of range"))

        # ORD-002
        if event == "UPDATE":
            owner_uid = _value(record, "OWNER_UID")
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                owner_uid,
                "ROLE_ID",
            )
            if disc_pct > 20 and role != "MGR" and role != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > 0):
                errors.append(_error("E5004", "Quantity must be positive"))

        # ORD-005
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
